def manufacturer_encode(value, size):
    if value is None or value is False:
        return None

    id_bytes = ((value & 0xFF00) >> 8).to_bytes(1, byteorder='big') + \
               (value & 0xFF).to_bytes(1, byteorder='big')

    if len(id_bytes) > size:
        return None

    return id_bytes

